  return draft.status === 'suggested' && !draft.blockers.length && !draft.duplicate_of
    && draft.to === fields.to && draft.subject === fields.subject && draft.body === fields.body
    && !!draft.to.trim() && !!draft.subject.trim() && !!draft.body.trim()
